#include <stdlib.h>
#include <stdio.h>
int main(void) {
    int *p = malloc(sizeof *p);
    if (p == NULL) return 1;
    *p = 7;
    int *q = p;
    printf("%d\n", *q);
    free(p);
    p = NULL;
    q = NULL;
    return 0;
}
// Before free: frame p --+
//                        > heap int [7]
//             frame q --/
// After free: heap object dead; both aliases must stop using it.
